TLM.f("Sancti/11-14",{"officium":"S. Josaphat Episcopi et Martyris","rule":["vide C2;"],"fallback":"Commune/C2","from":{"GradualeP":"Commune/C2","Tractus":"Commune/C2"},"sections":{"Introitus":[{"k":"text","la":"Gaudeámus omnes in Dómino, diem festum celebrántes sub honóre beáti Jósaphat Mártyris: de cujus passióne gaudent Angeli et colláudant Fílium Dei."},{"k":"ref","la":"Ps 32:1"},{"k":"text","la":"Exsultáte, justi, in Dómino: rectos decet collaudátio."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Gaudeámus omnes in Dómino, diem festum celebrántes sub honóre beáti Jósaphat Mártyris: de cujus passióne gaudent Angeli et colláudant Fílium Dei."}],"Oratio":[{"k":"text","la":"Excita, quǽsumus, Dómine, in Ecclésia tua Spíritum, quo replétus beátus Jósaphat Martyr et Póntifex tuus ánimam suam pro óvibus pósuit: ut, eo intercedénte, nos quoque eódem Spíritu moti ac roboráti, ánimam nostram pro frátribus pónere non vereámur."},{"k":"macro","name":"Per Dominum eiusdem"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Hebræos."},{"k":"ref","la":"Hebr 5:1-6"},{"k":"text","la":"Fratres: Omnis póntifex ex homínibus assúmptus, pro homínibus constitúitur in iis, quæ sunt ad Deum, ut ófferat dona, et sacrifícia pro peccátis: qui condolére possit iis, qui ígnorant et errant: quóniam et ipse circúmdatus est infirmitáte: et proptérea debet, quemádmodum pro pópulo, ita étiam et pro semetípso offérre pro peccátis. Nec quisquam sumit sibi honórem, sed qui vocátur a Deo, tamquam Aaron. Sic et Christus non semetípsum clarificávit, ut Póntifex fíeret: sed qui locútus est ad eum: Fílius meus es tu, ego hódie génui te. Quemádmodum et in álio loco dicit: Tu es sacérdos in ætérnum, secúndum órdinem Melchísedech."}],"Graduale":[{"k":"ref","la":"Ps 88:21-23"},{"k":"text","la":"Invéni David servum meum, óleo sancto meo unxi eum: manus enim mea auxiliábitur ei, et bráchium meum confortábit eum."},{"k":"text","la":"Nihil profíciet inimícus in eo, et fílius iniquitátis non nocébit ei. Allelúja, allelúja.","mark":"V"},{"k":"text","la":"Hic est sacérdos, quem coronávit Dóminus. Allelúja.","mark":"V"}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 88:6"},{"k":"text","la":"Confitebúntur cœli mirabília tua, Dómine: étenim veritátem tuam in ecclésia sanctórum. Allelúja."},{"k":"ref","la":"Ps 20:4"},{"k":"text","la":"Posuísti, Dómine, super caput ejus corónam de lápide pretióso. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 111:1-2"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Ps 20:3-4"},{"k":"text","la":"Desidérium ánimæ ejus tribuísti ei: et voluntáte labiórum ejus non fraudásti eum."},{"k":"text","la":"Quóniam prævenísti eum in benedictiónibus dulcédinis.","mark":"V"},{"k":"text","la":"Posuísti in cápite ejus corónam de lápide pretióso.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem"},{"k":"ref","la":"Joann 10:11-16"},{"k":"text","la":"In illo témpore: Dixit Jesus pharisǽis: Ego sum pastor bonus. Bonus pastor ánimam suam dat pro óvibus suis. Mercenárius autem et qui non est pastor, cujus non sunt oves própriæ, videt lupum veniéntem, et dimíttit oves et fugit: et lupus rapit et dispérgit oves: mercenárius autem fugit, quia mercenárius est et non pértinet ad eum de óvibus. Ego sum pastor bonus: et cognósco meas et cognóscunt me meæ. Sicut novit me Pater, et ego agnósco Patrem, et ánimam meam pono pro óvibus meis. Et álias oves hábeo, quæ non sunt ex hoc ovíli: et illas opórtet me addúcere, et vocem meam áudient, et fiet unum ovíle et unus pastor."}],"Offertorium":[{"k":"ref","la":"Joann 15:13"},{"k":"text","la":"Majórem caritátem nemo habet, ut ánimam suam ponat quis pro amícis suis."}],"Secreta":[{"k":"text","la":"Clementíssime Deus, múnera hæc tua benedictióne perfunde, et nos in fide confírma: quam sanctus Jósaphat Martyr et Póntifex tuus, effúso sánguine, asséruit."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Joannes 10:14"},{"k":"text","la":"Ego sum pastor bonus(, allelúja): et cognósco oves meas, et cognóscunt me meæ(, allelúja, allelúja)."}],"Postcommunio":[{"k":"text","la":"Spíritum, Dómine, fortitúdinis hæc nobis tríbuat mensa cœléstis: quæ sancti Jósaphat Mártyris tui atque Pontíficis vitam pro Ecclésiæ honóre júgiter áluit ad victóriam."},{"k":"macro","name":"Per Dominum"}]},"hr":{"d1d3e0d3fc4b96d5":{"t":"Ps 32, 1\nRadujmo se svi u Gospodinu slaveći blagdan na čast blaženog Jozafata mučenika, čijoj se muci raduju anđeli i slave Sina Božjega. (Ps 32, 1) Radujte se, pravednici, u Gospodinu; pravednima dolikuje pohvala.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\nRadujmo se svi u Gospodinu slaveći blagdan na čast blaženog Jozafata mučenika, čijoj se muci raduju anđeli i slave Sina Božjega.","kn":"Radujmo' se svi u Gospodinu slaveći svetkovinu na čast blaženog mučenika Tome, kojega se mučeništvu raduju anđeli slaveći Sina Božjega. (Ps. 32, 1) Radujte se pravednici u Gospodinu, pravednima, dolikuje hvala. Slava Ocu... Radujmo se . . .","knRef":"Kniewald 1942, str. 468–469 (snimka 235) (OCR)"},"a8f003f714bc9319":{"t":"<i>Pomolimo se</i>.\nProbudi, molimo, Gospodine, u svojoj Crkvi Duh, kojim je ispunjen blaženi Jozafat mučenik i biskup položio svoj život za ovce, da se i mi po njegovu zagovoru, tim istim Duhom potaknuti i ojačani, no bojimo svoj život položiti za braću.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu istog Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Probudi, molimo. Gospodine, u Crkvi svoj duh, kojeg je bio pun blaženi Josafat, Tvoj mučenik i biskup, te je svoj život dao za ovce svoje, da njegovim zagovorom i mi, potaknuti i ojačani istim Duhom, ne oklijevamo živote svoje dati za braću svoju, ipo G. n. . . . u jedinstvu istoga Duha .. .","knRef":"Kniewald 1942, str. 778–779 (snimka 390) (OCR)"},"bc848467d631bcb8":{"t":"Heb 5, 1-6\nČitanje Poslanice bl. Pavla apostola Hebrejima. Braćo, svaki veliki svećenik koji se od ljudi uzima, za ljude se postavlja na službu Bogu da prinosi darove i žrtve za grijehe. I može biti blag prema onima koji ne znaju i lutaju, jer je i sam podvrgnut slabosti. Zato je dužan, kako za grijehe naroda, tako i za svoje prinositi žrtve. 1 nitko sam sebi ne prisvaja časti, nego koji je pozvan od Boga, kao i Aron. Tako i Krist ne proslavi sam sebe, da bude veliki svećenik, nego onaj, koji mu reče: Ti si Sin moj, ja sam te danas rodio. Kao što i na drugom mjestu govori: Ti si svećenik dovijeka po redu Melkisedekovu.","kn":"Čitanje poslanice bi. Pavla apostola Hebrejima (5, 1-6). Braćo! Svaki veliki svećenik, uzet od ljudi, postavlja se za ljude, da služi u onim stvarima, koje se odnose na Boga, da prinosi darove i žrtve za grijehe, da može trpjeti zajedno s onima, koji ne znaju i lutaju, jer je i sam podložan sla,bostima. Zato je i dužan prinositi žrtve za grijehe, kako za narod, tako i za sebe. Neka nitko sam ne uzima časti, nego koji je pozvan od Boga, kao što Aron. Tako i Krist nije sam proglasio sebe velikim svećenikom, nego onaj, koji mu je rekao: Ti si moj Sin, ja sam te danas rodio. Kao što kaže i na drugom mjestu: Ti si svećenik u vi jeke po redu Melkisedekovu!","knRef":"Kniewald 1942, str. 468–469 (snimka 235) (OCR)"},"f1d80db4f643dc65":{"t":"Ps 88, 21-23\nNašao sam Davida, slugu svojega, pomazao sam ga svojim svetim uljem. S njim će biti ruka moja i krijepit će ga desnica moja. Neprijatelj biti nemoćan prema njemu, i sin bezakonja neće se usuditi da mu naškodi.\n\n<i>Aleluja</i>, <i>aleluja</i>.\nOvo je svećenik koga je okrunio Gospodin. <i>Aleluja</i>.","kn":"(Ps. 88, 21-23). Izabrah Davida slu- ,gu moga i pomazah ga uljem svetim; jer ruka moja (Ppmoze njemu i moja ga mišica jača. Neprijatelj mu ne će ništa naškoditi i sin zloće ne će mu nauditi.\n\nAleluja, aleluja! Ovo je svećenik, koga je okrunio Gospođin, aleluja!","knRef":"Kniewald 1942, str. 452–453 (snimka 227) (OCR)"},"24aa582fd8f56d69":{"t":"Iv 10, 11-16\nSlijedi sveto Evanđelje po Ivanu. U ono vrijeme: reče Isus farizejima: Ja sam dobri pastir. Dobar pastir daje svoj život za svoje ovce, a najamnik, koji nije pastir i nije vlasnik ovaca, kad vidi da dolazi vuk, ostavi ovce i bježi, pa vuk grabi i razgoni ovce. Najamnik bježi, jer je najamnik i nije mu stalo do ovaca. Ja sam dobri pastir i poznajem svoje ovce, a moje ovce poznaju mene, kao što Otac poznaje mene i kao što ja poznajem Oca. I ja dajem svoj život za svojeg ovce. Imam i drugih ovaca, koje nisu iz ovog ovčinjaka. I njih mi treba dovesti i čut će moj glas i bit će jedno stado i jedan pastir.","kn":"t Slijedi sveto evanđelje po Ivanu (10, 11-16). U ono vrijeme reče Isus farizejima: Ja sam dobri pastir. Dobri pastir polaže svoji život za svoje .ovce. A najamnik, koji nije pastir, koji nema svojih ovaca, kad vidi, da dolazi vuk, ostavlja o-vce i bježi, a vuk ih grabi 1 razgoni. Najamnik bježi jer je najamnik i nije mu stalo do ovaca. Ja sam dobri pastir i poznajem svoje ovce, a moje poznaju mene. Ka-o što mene poznaje Otac, i ja poznajem Oca, i svoj život polažem za svoje ovce. Imam i drugih ovaca, koje nijesu iz ovog ovčinjaka. Ali i one Sv. Josip, zaštitnik sv. Crkve treba da dovedem, i slušat će moj glas i bit će jedno stado 1 jedan pastir.","knRef":"Kniewald 1942, str. 320–321 (snimka 161) (OCR)"},"104514d910bceb4c":{"t":"Iv 15, 13\nOd ove ljubavi nitko veće nema da dade život svoj za prijatelje svoje.","v":"ista misa na staroj stranici, latinski tekst odstupa (sličnost 0.88)"},"79c937dc773d73f9":{"t":"[preveo M.B.] Premilostivi Bože, izlij svoj blagoslov na darove ove darove i učvrsti nas i vjeri, koju je Jozafat, tvoj mučenik i biskup potvrdio prolivenom krvlju.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože, po Kristu, Gospotdiniu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i blaženi serafini, zadružnim klicanjem zajedno slave. Zapovijedi, molimo, da se i naši glasovi združe s njihovima, smjernim isippvijedanjem govoreći:","knRef":"Kniewald 1942, str. 18–19 (snimka 10) (OCR)"},"fa7c19ac6bf4e7bf":{"t":"Iv 10, 14\nJa sam dobri pastir i poznam svoje ovce, a moje ovce poznaju mene.","kn":"(Iv. 10, 14). Ja sam dobri pastir i poznam ovce svoje i one poznaju mene.","knRef":"Kniewald 1942, str. 468–469 (snimka 235) (OCR)"},"e937765d522be2f5":{"t":"<i>Pomolimo se</i>.\nNeka nam, Gospodine, ova nebeska gozba udijeli duh one jakosti, koja je život svetoga Jozafata mučenika i biskupa na čast Crkve hranila sve do pobjede.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
